INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 33, 'theory', 'Quiz: registries and supply chain security');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 0, 'What does the dist-tag latest mean?', '["The newest version by publication date", "A label showing which version is installed by default", "A version marked as deprecated", "A prerelease"]', 1, 'Tags are movable labels in the metadata. npm install pkg takes the version latest points to; prereleases are published with --tag next.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 1, 'What is dependency confusion?', '["A version conflict in the tree", "An attacker publishes a package to the public registry with the name of an internal package and a higher version", "A typo in a package name", "A duplicate in the lockfile"]', 1, 'If the manager looks in the public registry for an internal name, it may pick the "newer" malicious package. Defense: bind the scope to your own registry and reserve the names.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 2, 'What does integrity (the archive hash) in the lockfile protect against?', '["Malicious code published by the author", "Archive tampering: the manager checks the hash after downloading", "Outdated dependencies", "License conflicts"]', 1, 'The hash confirms that the archive is the same as when the lockfile was made. It doesn''t guarantee that the code is safe.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 3, 'What does provenance give you when publishing from CI?', '["Faster installs", "A signed record: which repository, commit and workflow the package was built from", "Encryption of the package code", "Hidden sources"]', 1, 'Provenance (Sigstore) ties the package to a specific build, which lets you verify its origin.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 4, 'What does the license "MIT OR Apache-2.0" mean?', '["You must comply with both licenses", "The user picks either of the two", "The license is undefined", "You can''t use it"]', 1, 'In SPDX expressions, OR means choosing one of the licenses, AND means an obligation to comply with both.');
